                remove_delta = dist(prev1, c) + dist(c, next1) - dist(prev1, next1)
                best = None
                for j in range(len(routes)):
                    if i == j:
                        continue
                    r2 = routes[j]
                    if route_load(r2) + dc > capacity + 1e-9:
                        continue
                    for ins in range(len(r2) + 1):
                        prev2 = 0 if ins == 0 else r2[ins - 1]
                        next2 = 0 if ins == len(r2) else r2[ins]
                        add_delta = dist(prev2, c) + dist(c, next2) - dist(prev2, next2)
                        delta = add_delta - remove_delta
                        if delta < -1e-12 and (best is None or delta < best[0] - 1e-12 or (abs(delta - best[0]) <= 1e-12 and (j, ins) < (best[1], best[2]))):
                            best = (delta, j, ins)
                if best is not None:
                    _, j, ins = best
                    c = r1.pop(pos)
                    routes[j].insert(ins, c)
                    changed = True
                    break

        routes = [r for r in routes if r]

        if changed:
            continue

        for i in range(len(routes)):
            if changed:
                break
            for j in range(i + 1, len(routes)):
                r1 = routes[i]
                r2 = routes[j]
                l1 = route_load(r1)
                l2 = route_load(r2)
                for a_idx, a in enumerate(r1):
                    da = demand[a]
                    for b_idx, b in enumerate(r2):
                        db = demand[b]
                        if l1 - da + db > capacity + 1e-9 or l2 - db + da > capacity + 1e-9:
                            continue
                        pa = 0 if a_idx == 0 else r1[a_idx - 1]
                        na = 0 if a_idx == len(r1) - 1 else r1[a_idx + 1]
                        pb = 0 if b_idx == 0 else r2[b_idx - 1]
                        nb = 0 if b_idx == len(r2) - 1 else r2[b_idx + 1]
                        before = dist(pa, a) + dist(a, na) + dist(pb, b) + dist(b, nb)
                        after = dist(pa, b) + dist(b, na) + dist(pb, a) + dist(a, nb)
                        if after + 1e-12 < before:
                            r1[a_idx], r2[b_idx] = b, a
                            changed = True
                            break
                    if changed:
                        break

    routes = [r for r in routes if r]
    return routes
